const icons={visitor:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3M3 12h3m12 0h3"/>',warden:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7Z"/><path d="m8 12 3 3 5-6"/>',security:'<path d="M4 21V5h16v16M2 21h20M8 9h8M8 13h8M12 5v16"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',camera:'<path d="M3 7h12v12H3zM15 11l6-4v12l-6-4M6 7l2-3h5l2 3"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]}</svg>`;
const key='amrita-visits-v1',logKey='amrita-audit-v1';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const demo=()=>[{id:'AMV-DEMO01',visitor:'Lakshmi Kumar',phone:'9000000001',relation:'Parent',plate:'TN38AB1234',student:'Arjun Kumar',studentId:'CB.CSE.DEMO01',branch:'Computer Science',hostel:'Anugraha',warden:'Dr. R. Menon',purpose:'Family visit',date:today(),status:'approved',created:new Date().toISOString()},{id:'AMV-DEMO02',visitor:'Suresh Nair',phone:'9000000002',relation:'Guardian',plate:'KL07CD5678',student:'Meera Nair',studentId:'CB.ECE.DEMO02',branch:'Electronics & Communication',hostel:'Amritamayi',warden:'Dr. S. Devi',purpose:'Parent visit',date:today(),status:'pending',created:new Date().toISOString()}];
let visits;try{visits=JSON.parse(localStorage.getItem(key))||demo()}catch{visits=demo()}let logs;try{logs=JSON.parse(localStorage.getItem(logKey))||[]}catch{logs=[]}
let viewFilter='all',gate='entry',foundId=null,originalPlate='';
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plate=v=>v.toUpperCase().replace(/[^A-Z0-9]/g,'');
const stamp=v=>v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'—';
const labels={pending:'Entry pending',approved:'Entry approved',inside:'Inside campus',exit:'Exit approved',completed:'Completed',rejected:'Rejected',expired:'Expired'};
const effective=v=>['pending','approved'].includes(v.status)&&v.date<today()?'expired':v.status;
const badge=v=>`<span class="status ${effective(v)}">${labels[effective(v)]}</span>`;
function save(){try{localStorage.setItem(key,JSON.stringify(visits));localStorage.setItem(logKey,JSON.stringify(logs))}catch{toast('Browser storage is unavailable. Keep this page open to retain your session.')}}
function audit(action,v,extra={}){logs.unshift({action,visit:v.id,plate:v.plate,time:new Date().toISOString(),...extra});save()}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',4500)}
function heading(eyebrow,title,desc){return `<a class="back" href="#home">← Back to portals</a><div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="intro">${desc}</p></div><div class="tabs"><a class="tab ${location.hash==='#visitor'?'active':''}" href="#visitor">Visitor portal</a><a class="tab ${location.hash==='#warden'?'active':''}" href="#warden">Warden dashboard</a><a class="tab ${location.hash==='#security'?'active':''}" href="#security">Security dashboard</a></div>`}
function home(){app.innerHTML=`<div class="hero-row"><div><div class="eyebrow">WELCOME TO THE CAMPUS ACCESS PORTAL</div><h1>AMRITA UNIVERSITY<br><span>ENTRY MONITORING SYSTEM</span></h1><p class="intro">A connected journey from visitor request to verified departure.<br>Manage campus visits with warden approvals and vehicle recognition.</p></div><div class="location"><strong>Coimbatore campus</strong>Tamil Nadu, India<br><span class="live-dot"></span>Visitor management system</div></div><div class="section-label"><h2>Choose your portal</h2><span>Three roles. One coordinated workflow.</span></div><section class="portals">${[['visitor','01 / PLAN YOUR VISIT','Visitor portal','Request permission to meet a student. Track your entry and exit approvals.','VISITOR REQUEST'],['warden','02 / REVIEW & VERIFY','Warden dashboard','Review visit requests and authorize entry. Verify the visit before approving exit.','WARDEN APPROVAL'],['security','03 / MONITOR THE GATE','Security dashboard','Check vehicle plates and approval status. Record verified entry and departure.','SECURITY MONITORING']].map(([n,s,t,d,l])=>`<article class="portal"><div class="portal-content"><div class="icon-box">${icon(n)}</div><small>${s}</small><h3>${t}</h3><p>${d}</p></div><a class="portal-link" href="#${n}">${l}<span class="angle">${icon('arrow')}</span></a></article>`).join('')}</section><div class="lower"><section class="panel"><h2>Every visit, accounted for</h2><div class="steps">${[['01','Submit a request','Visitor shares vehicle and student details.'],['02','Approve entry','Assigned warden reviews the request.'],['03','Verify the visit','Warden authorizes the visitor’s exit.'],['04','Record departure','Security confirms exit permission.']].map(([n,t,d])=>`<div class="step"><div class="step-number">${n}</div><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></section><section class="panel"><h2>Before you arrive</h2><div class="notice"><b>↗</b><p>Get your warden’s approval first.<span>A submitted request is awaiting permission until approved.</span></p></div><div class="notice"><b>✓</b><p>Travel in your registered vehicle.<span>Use the same number plate entered in your request.</span></p></div><div class="notice"><b>◎</b><p>Demo workspace<span>Data is saved in this browser. Camera recognition is simulated.</span></p></div></section></div>`}
function visitor(){app.innerHTML=heading('PLAN YOUR CAMPUS VISIT','Visitor <span>request</span>','Share your visit details. Your assigned warden will review your request before arrival.')+`<div class="form-layout"><form id="visit-form" class="panel"><h2 class="form-section">Visitor information</h2><div class="form-grid"><label class="field">Full name *<input name="visitor" required maxlength="80" placeholder="Enter visitor’s full name"></label><label class="field">Phone number *<input name="phone" required pattern="[0-9]{10}" inputmode="tel" maxlength="10" placeholder="10-digit mobile number"></label><label class="field">Relationship *<select name="relation"><option>Parent</option><option>Guardian</option><option>Other visitor</option></select></label><label class="field">Vehicle registration number *<input name="plate" required pattern="[A-Za-z0-9 -]{6,16}" maxlength="16" placeholder="e.g. TN 38 AB 1234"></label></div><h2 class="form-section">Person you are visiting</h2><div class="form-grid"><label class="field">Student / university ID *<input name="studentId" required placeholder="Enter university ID"></label><label class="field">Student / person’s full name *<input name="student" required maxlength="80" placeholder="Enter full name"></label><label class="field">Branch / department *<select name="branch"><option>Computer Science</option><option>Artificial Intelligence</option><option>Electronics & Communication</option><option>Electrical & Electronics</option><option>Mechanical Engineering</option><option>Other department</option></select></label><label class="field">Hostel / assigned warden *<select name="assignment"><option value="Anugraha|Dr. R. Menon">Anugraha · Dr. R. Menon (demo)</option><option value="Amritamayi|Dr. S. Devi">Amritamayi · Dr. S. Devi (demo)</option></select></label><label class="field">Visit date *<input name="date" type="date" required min="${today()}" value="${today()}"></label><label class="field">Purpose of visit *<input name="purpose" required maxlength="180" placeholder="e.g. Family visit"></label></div><label class="check"><input type="checkbox" required><span>I confirm that these details are correct and understand that warden approval is required before entry.</span></label><div class="actions"><button class="btn" type="submit">Submit visit request →</button><span class="hint">* Required fields</span></div></form><aside><section class="panel"><h2>Track your request</h2><p class="hint">Enter the request ID issued after submission.</p><form id="track-form"><label class="field">Request ID<input id="track-id" required placeholder="AMV-…"></label><button class="btn secondary" style="margin-top:12px">Check status</button></form><div id="track-result" aria-live="polite"></div></section><section class="panel" style="margin-top:20px"><h2>A little preparation helps</h2><p class="hint">01 &nbsp; Request approval before travelling.<br>02 &nbsp; Keep your request ID with you.<br>03 &nbsp; Arrive in the registered vehicle.<br>04 &nbsp; Meet the warden for exit approval.</p><p class="hint">Warden names and hostel mappings in this prototype are sample data.</p></section></aside></div>`;
document.querySelector('#visit-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const [hostel,warden]=d.assignment.split('|');if(d.date<today()){toast('Choose today or a future visit date.');return}const v={...d,plate:plate(d.plate),hostel,warden,id:'AMV-'+crypto.randomUUID().slice(0,8).toUpperCase(),status:'pending',created:new Date().toISOString()};visits.unshift(v);audit('Request submitted',v,{actor:'Visitor'});e.target.reset();document.querySelector('#track-id').value=v.id;showTracking(v.id);toast('Request submitted. Save your request ID: '+v.id)};
document.querySelector('#track-form').onsubmit=e=>{e.preventDefault();showTracking(document.querySelector('#track-id').value.trim().toUpperCase())}}
function showTracking(id){const v=visits.find(v=>v.id===id);document.querySelector('#track-result').innerHTML=v?`<div class="visit-card"><strong>${esc(v.id)}</strong><p>${esc(v.visitor)} · ${esc(v.plate)}<br>Visiting ${esc(v.student)}<br>${esc(v.date)} · ${esc(v.warden)}</p>${badge(v)}<p>Entry: ${stamp(v.entered)}<br>Exit: ${stamp(v.exited)}</p></div>`:'<p class="hint">No request found. Check the request ID.</p>'}
function stats(){return `<div class="stats">${[['Total visits',visits.length],['Awaiting entry approval',visits.filter(v=>effective(v)==='pending').length],['Inside campus',visits.filter(v=>['inside','exit'].includes(v.status)).length],['Completed visits',visits.filter(v=>v.status==='completed').length]].map(([s,n])=>`<div class="stat"><strong>${n}</strong><span>${s}</span></div>`).join('')}</div>`}
function warden(){app.innerHTML=heading('REVIEW & AUTHORIZE','Warden <span>dashboard</span>','Approve arrival requests and verify completed visits before authorizing departure.')+stats()+`<section class="panel"><div class="section-label" style="margin-top:0"><h2>Visit requests</h2><label class="field">Assigned warden<select id="warden-filter"><option value="all">All wardens (demo)</option><option>Dr. R. Menon</option><option>Dr. S. Devi</option></select></label></div><p class="hint">Prototype: role access is open for demonstration. Exit approval confirms that the visitor and student have met the warden.</p><div class="table-scroll"><table><thead><tr><th>Visitor / vehicle</th><th>Student / department</th><th>Visit / warden</th><th>Status</th><th>Action</th></tr></thead><tbody>${visits.filter(v=>viewFilter==='all'||v.warden===viewFilter).map(v=>`<tr><td><strong>${esc(v.visitor)}</strong>${esc(v.plate)}<br><small>${esc(v.id)} · ${esc(v.relation)}</small></td><td><strong>${esc(v.student)}</strong>${esc(v.branch)}<br><small>${esc(v.studentId)}</small></td><td>${esc(v.date)}<br>${esc(v.warden)}<br><small>${esc(v.purpose)}</small></td><td>${badge(v)}</td><td>${effective(v)==='pending'?`<button class="btn table-btn" data-action="approve" data-id="${v.id}">Approve entry</button> <button class="btn danger table-btn" data-action="reject" data-id="${v.id}">Reject</button>`:v.status==='inside'?`<label class="check" style="margin:0 0 8px"><input type="checkbox" data-verify="${v.id}">Visitor and student verified</label><button class="btn table-btn" data-action="exit" data-id="${v.id}">Approve exit</button>`:'<small>No action required</small>'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No requests for this warden.</td></tr>'}</tbody></table></div></section>`;const select=document.querySelector('#warden-filter');select.value=viewFilter;select.onchange=()=>{viewFilter=select.value;warden()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const v=visits.find(v=>v.id===b.dataset.id);if(b.dataset.action==='exit'&&!document.querySelector(`[data-verify="${v.id}"]`).checked){toast('Confirm that you have verified the visitor and student first.');return}v.status={approve:'approved',reject:'rejected',exit:'exit'}[b.dataset.action];audit({approve:'Entry approved',reject:'Request rejected',exit:'Exit approved'}[b.dataset.action],v,{actor:v.warden});warden();toast('Visit status updated.')})}
function security(){foundId=null;app.innerHTML=heading('VERIFY & RECORD','Security <span>dashboard</span>','Check the registered vehicle against the visit approval before confirming passage.')+stats()+`<div class="security-grid"><section class="panel"><div class="section-label" style="margin-top:0"><h2>Gate monitoring</h2><span>ANPR simulation</span></div><div class="tabs"><button class="tab ${gate==='entry'?'active':''}" data-gate="entry">Entry gate</button><button class="tab ${gate==='exit'?'active':''}" data-gate="exit">Exit gate</button></div><div class="camera"><span class="camera-label">${gate.toUpperCase()} CAMERA · DEMO FEED</span>${icon('camera')}<span>Camera integration pending</span><div class="plate-preview" id="plate-preview">TN38AB1234</div><span style="font-size:11px">Simulate a reading to demonstrate the approval check.</span></div><div class="scan-controls"><button class="btn" id="simulate">Simulate plate scan</button><button class="btn secondary" id="simulate-error">Simulate misread</button></div><label class="field" style="margin-top:20px">Recognized plate / guard correction<input id="plate-input" placeholder="Type or correct the visible vehicle number" maxlength="16"></label><div class="actions"><button class="btn secondary" id="lookup">Check approval →</button></div><p class="hint">Guard correction triggers a fresh permission check. A matched plate still requires visual verification.</p></section><section class="panel"><h2>Vehicle approval status</h2><div id="gate-result" aria-live="polite"><div class="result-banner">Awaiting vehicle lookup<br><small>Scan or enter a plate to check its visit request.</small></div></div></section></div><section class="panel" style="margin-top:22px"><h2>Gate activity & approval history</h2><div class="table-scroll"><table><thead><tr><th>Time (IST)</th><th>Vehicle</th><th>Activity</th><th>Recorded by</th></tr></thead><tbody>${logs.slice(0,30).map(l=>`<tr><td>${stamp(l.time)}</td><td>${esc(l.plate)}<br><small>${esc(l.visit)}</small></td><td>${esc(l.action)}${l.original&&l.original!==l.plate?`<br><small>Original reading: ${esc(l.original)}</small>`:''}</td><td>${esc(l.actor)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity yet. Complete a sample visit to see its history.</td></tr>'}</tbody></table></div></section>`;
document.querySelectorAll('[data-gate]').forEach(b=>b.onclick=()=>{gate=b.dataset.gate;security()});document.querySelector('#simulate').onclick=()=>scan(false);document.querySelector('#simulate-error').onclick=()=>scan(true);document.querySelector('#lookup').onclick=lookup;document.querySelector('#plate-input').oninput=()=>{foundId=null;document.querySelector('#gate-result').innerHTML='<div class="result-banner">Plate changed. Check approval again before confirming passage.</div>'}}
function scan(error){const candidate=visits.find(v=>gate==='exit'?['inside','exit'].includes(v.status):effective(v)==='approved')||visits[0];if(!candidate){toast('Submit a visitor request first.');return}originalPlate=error?candidate.plate.slice(0,-1)+(candidate.plate.endsWith('8')?'6':'8'):candidate.plate;document.querySelector('#plate-input').value=originalPlate;document.querySelector('#plate-preview').textContent=originalPlate;lookup()}
function lookup(){const input=document.querySelector('#plate-input');const p=plate(input.value);input.value=p;foundId=null;if(!p){toast('Enter a vehicle registration number.');return}const matches=visits.filter(v=>v.plate===p&&v.date===today()&&!['completed','rejected'].includes(v.status));const result=document.querySelector('#gate-result');if(matches.length!==1){result.innerHTML=`<div class="result-banner bad">${matches.length>1?'Multiple active requests found':'No active visit found'}<br><small>${matches.length>1?'Resolve duplicate visit requests with the warden before passage.':'Check the visible number plate and the visit date. Warden approval is required.'}</small></div>`;return}const v=matches[0];foundId=v.id;const allowed=gate==='entry'?v.status==='approved':v.status==='exit';result.innerHTML=`<div class="result-banner ${allowed?'good':''}"><strong>${allowed?gate==='entry'?'Entry approved':'Exit approved':gate==='entry'?v.status==='pending'?'Entry approval pending':'Vehicle already inside campus':v.status==='inside'?'Exit approval pending':'Vehicle has not entered campus'}</strong><br><small>${allowed?'Verify the visitor and vehicle before confirming actual passage.':'Contact the assigned warden for the required verification.'}</small></div><div class="result-details">${[['Visitor',v.visitor],['Relationship',v.relation],['Vehicle number',v.plate],['Request ID',v.id],['Student / person',v.student],['University ID',v.studentId],['Department',v.branch],['Assigned warden',v.warden],['Visit date',v.date],['Entry recorded',stamp(v.entered)]].map(([k,val])=>`<div><span>${k}</span><strong>${esc(val)}</strong></div>`).join('')}</div>${allowed?`<label class="check"><input id="guard-verified" type="checkbox">I have verified the visible plate and visitor details, and the vehicle is passing the gate.</label><button class="btn" id="confirm-passage" style="margin-top:17px">Confirm ${gate==='entry'?'entry':'departure'} →</button>`:''}`;if(allowed)document.querySelector('#confirm-passage').onclick=()=>{if(!document.querySelector('#guard-verified').checked){toast('Verify the vehicle and confirm actual passage first.');return}const current=visits.find(x=>x.id===foundId);if(!current||plate(input.value)!==current.plate||current.date!==today()||current.status!==(gate==='entry'?'approved':'exit')){lookup();return}current.status=gate==='entry'?'inside':'completed';current[gate==='entry'?'entered':'exited']=new Date().toISOString();audit(gate==='entry'?'Vehicle entered':'Vehicle departed',current,{actor:'Security guard (demo)',original:originalPlate||current.plate});originalPlate='';security();toast(gate==='entry'?'Entry recorded. Exit requires separate warden approval.':'Departure recorded. Visit completed.')}}
function render(){const route=location.hash||'#home';if(route==='#visitor')visitor();else if(route==='#warden')warden();else if(route==='#security')security();else home()}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('storage',()=>{try{visits=JSON.parse(localStorage.getItem(key))||visits;logs=JSON.parse(localStorage.getItem(logKey))||logs;render()}catch{}});save();render();
